#define MAX_FILE_NAME_LEN FSI_NAME_MAX
#define MAX_FILES 50000

// returns 1 if found and matched, 0 if not found (unexpected entry!), -1 if found but already seen (duplicate!)
int fsi_fuzzy_cwl_expected_entry_check_off(expected_entry_list *entries, const char *path, uint64_t path_len, FSI_OS_FILE_TYPE type) {
    for (int i = 0; i < entries->count; i++) {
        if (strlen(entries->entries[i].path) == path_len && strncmp(entries->entries[i].path, path, path_len) == 0) {
            if (entries->entries[i].seen) return -1;            // duplicate pop -- bug!
            if (entries->entries[i].type != type) return 0;     // type mismatch -- bug!
            entries->entries[i].seen = 1;
            return 1;
        }
    }
    return 0;   // path never created -- bug!
}

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    if(size == 0) {
        return 0;
    }

    size_t pos = 0;

    char test_path[FSI_PATH_MAX];
    uint64_t test_path_len = fsi_get_test_root(test_path, FSI_PATH_MAX);
    //printf("test_path %s\n", test_path);

    fsi_os_directory_create(test_path);

    expected_entry_list* expected_list = calloc(1, MAX_FILES * sizeof(expected_entry));
    expected_list->count = 0;
    expected_list->size = MAX_FILES;
    uint64_t file_count = create_test_tree_for_fuzzer_data(data, size, &pos, test_path, test_path_len, expected_list, MAX_FILES);
    
    fsi_t_cwl_config cwl_cfg = {
        .parallelismn = 1
    };

    fsi_t_cwl_crawler* crawler = fsi_cwl_create_crawler(&cwl_cfg);
    if(crawler == NULL) {
        remove_test_dir_recursive(test_path);
        free(expected_list);
        return 0;
    }

    const char* path_list[] = { test_path };

    fsi_cwl_crawler_init(crawler, path_list, 1);

    int interrupted = 0;
    fsi_cwl_crawl_process_loop(&crawler->context, &interrupted, FSI_QUEUE_NON_BLOCKING);
    
    fsi_t_cwl_context* context = &crawler->context;
    fsi_file_info info;
    //needed because otherwise queue is blocking when empty
    while (context->file_queue->count > 0) {
        if (fsi_queue_pop(context->file_queue, &info, FSI_QUEUE_NON_BLOCKING) == FSI_QUEUE_OK) {
            int result = fsi_fuzzy_cwl_expected_entry_check_off(expected_list, info.file_path, info.file_path_len, info.type);
            if (result != 1) {
                abort();   // unexpected, duplicate, or type-mismatched entry -- real bug found
            }
        }
    }

    remove_test_dir_recursive(test_path);
    fsi_cwl_destroy_crawler(crawler);
    free(expected_list);
    return 0;
}

